fn is_prime(n: i8) -> bool {
    if n < 2 {
        return false;
    }

    // Use i16 to avoid overflow in arithmetic and modulus checks - optional but safer
    let n = n as i16;

    let mut candidate = 2i16;
    while candidate < n {
        if n % candidate == 0 {
            return false;
        }
        candidate += 1;
    }

    true
}